export function catalogueFor(locale: string): Messages {
  return CATALOGUES[String(locale).toLowerCase()] || CATALOGUES[DEFAULT_LOCALE]
}

/**
 * Every locale, keyed by code.
 *
 * Exported because it is the only complete answer to "what does this app
 * actually have?", and because a test needs to assert the registry holds
 * locales and nothing else. A stray string property here is invisible to every
 * other check: it is neither a locale anyone selects nor a key the product
 * asks for, so it just sits there reading as coverage.
 */
export const CATALOGUES: Record<string, Messages> = {
  en, sw, fr, ar, es, pt, de, it, nl, zh, hi, ja, ko, rw, ug,
}

export type TranslateValues = Record<string, string | number>

export type TranslateFn = (key: string, values?: TranslateValues) => string

/**
 * Build a translate function for a locale.
 *
 * `fallbackLocale` exists for a reason that is easy to get wrong: an
 * untranslated string should be the ENGLISH one, not a raw key. A raw key in
 * the interface tells a user nothing; readable English tells them what the
 * feature is even if the app is not fully localised yet.
 */
export function createTranslator(
  locale: string,
  options: {
    onMissing?: (key: string) => void
    /**
     * Override the catalogues. Only for tests.
     *
     * The fallback path - "this locale has not translated that key, so use
     * English" - is the single most important behaviour in this file, and it
     * used to be tested by borrowing a production key that happened to be
     * untranslated. Closing the catalogue gap made every locale complete, and
     * with nothing left to be missing the four tests covering fallback began
     * failing for the right reason: they had no gap to exercise.
     *
     * Injecting the catalogues lets a test state the condition directly rather
     * than waiting for the product to be incomplete. Nothing in the app passes
     * this option.
     */
    catalogues?: { primary: Messages; fallback: Messages }
  } = {}
): TranslateFn & { missing: (key: string) => boolean } {
  const primary = options.catalogues ? options.catalogues.primary : catalogueFor(locale)
  const fallback = options.catalogues ? options.catalogues.fallback : catalogueFor(DEFAULT_LOCALE)
  const isDefault = options.catalogues
    ? false
    : getLocale(locale).code === DEFAULT_LOCALE

  // Reported once per key. The dedup belongs here rather than in the provider,
  // because a provider-level dedup only works for the one provider instance -
  // any direct call to this translator reported the same missing key on every
  // render, which is how a coverage report inflates itself into uselessness.
  const reported = new Set<string>()

  const t = ((key: string, values?: TranslateValues): string => {
    let template = primary[key]

    if (template === undefined) {
      if (!isDefault && !reported.has(key)) {
        reported.add(key)
        options.onMissing?.(key)
      }
      template = fallback[key]
    }

    // A key with no entry anywhere is a bug in the caller, not a translation
    // gap. Surfacing the key makes it greppable, which is more useful than an
    // empty string.
    if (template === undefined) return key

    if (!values) return template
    return template.replace(/\{(\w+)\}/g, (match, name: string) =>
      values[name] === undefined ? match : String(values[name])
    )
  }) as TranslateFn & { missing: (key: string) => boolean }

  t.missing = (key: string) =>
    primary[key] === undefined && fallback[key] !== undefined && !isDefault

  return t
}

/** How much of a locale is actually translated. */
export function coverage(locale: string): {
  locale: string
  translated: number
  total: number
  percent: number
  missing: string[]
} {
  const all = Object.keys(en)
  const cat = catalogueFor(locale)
  const missing = all.filter(k => cat[k] === undefined)
  const translated = all.length - missing.length
  return {
    locale,
    translated,
    total: all.length,
    percent: all.length === 0 ? 0 : Math.round((translated / all.length) * 100),
    missing,
  }
}

/** Every locale with its coverage, for a progress report. */
export function allCoverage(): Record<string, ReturnType<typeof coverage>> {
  const out: Record<string, ReturnType<typeof coverage>> = {}
  for (const code of Object.keys(CATALOGUES)) {
    out[code] = coverage(code)
  }
  return out
}























/** Keys present in English but in no other catalogue - the extraction TODO list. */
export function untranslatedKeys(): string[] {
  const others = Object.keys(CATALOGUES).filter(c => c !== DEFAULT_LOCALE)
  return Object.keys(en).filter(k => others.some(c => catalogueFor(c)[k] === undefined))
}
